"""Tests for viewpie_layout_engine.generator (and model sanity)."""

from __future__ import annotations

import pytest
import yaml

from viewpie_layout_engine.generator import (
    blocks_to_layout_text,
    camera_to_feed,
    generate_panel_yaml,
    generate_viewpie_yaml,
)
from viewpie_layout_engine.models import Block, Camera, DisplaySettings, Panel, Viewport


@pytest.fixture()
def cameras() -> dict[str, Camera]:
    return {
        "cam1": Camera(name="cam1", url="rtsp://192.168.1.10/stream1"),
        "cam2": Camera(
            name="cam2",
            url="rtsps://host/cam2",
            fullscreen_url="rtsp://host/cam2_full",
        ),
    }


@pytest.fixture()
def panel() -> Panel:
    layout = "cam1 cam1 cam2\ncam1 cam1 .\n. . ."
    return Panel(
        id="main",
        name="Main wall",
        layout=layout,
        viewports=[Viewport(slot="s1", feeds=["cam1"], rotation_interval=30)],
        spacing=2,
        background="#101010",
    )


def test_generate_full_yaml_has_all_sections(panel: Panel, cameras: dict[str, Camera]) -> None:
    """Top-level keys display/feeds/panels/defaults must all exist."""
    text = generate_viewpie_yaml(cameras, [panel], DisplaySettings(), "main")
    doc = yaml.safe_load(text)
    assert set(doc) >= {"display", "feeds", "panels", "defaults"}
    assert doc["display"]["spacing"] == 1
    assert doc["display"]["pause_off_screen"] is True
    assert doc["display"]["background"] == "#000000"
    assert doc["defaults"]["panel"] == "main"
    assert doc["defaults"]["rotation_interval"] == 20
    assert doc["defaults"]["fullscreen_timeout"] == 600


def test_feeds_section_contains_urls(panel: Panel, cameras: dict[str, Camera]) -> None:
    """Registered cameras referenced by viewports appear under feeds."""
    text = generate_viewpie_yaml(cameras, [panel], DisplaySettings(), "main")
    doc = yaml.safe_load(text)
    assert doc["feeds"]["cam1"]["url"] == "rtsp://192.168.1.10/stream1"
    assert doc["feeds"]["cam2"]["fullscreen_url"] == "rtsp://host/cam2_full"


def test_panel_layout_survives_roundtrip(panel: Panel, cameras: dict[str, Camera]) -> None:
    """The multi-line block scalar parses back into identical layout text."""
    text = generate_viewpie_yaml(cameras, [panel], DisplaySettings(), "main")
    doc = yaml.safe_load(text)
    assert doc["panels"][0]["layout"] == panel.layout
    assert doc["panels"][0]["viewports"][0]["slot"] == "s1"


def test_generated_yaml_is_valid_yaml(cameras: dict[str, Camera]) -> None:
    """Output always loads with a strict YAML parser."""
    layout = "a b c\nd e f\ng h i"
    p = Panel(id="p1", name="P1", layout=layout, viewports=[])
    text = generate_viewpie_yaml(cameras, [p], DisplaySettings(spacing=5), "p1")
    doc = yaml.safe_load(text)
    assert doc["display"]["spacing"] == 5
    assert text.startswith("# Generated by viewpie-layout-engine")


def test_unknown_active_panel_raises(cameras: dict[str, Camera]) -> None:
    """Guard against referencing a non-existent panel as default."""
    p = Panel(id="p1", name="P1", layout="a b c\nd e f\ng h i", viewports=[])
    with pytest.raises(ValueError):
        generate_viewpie_yaml(cameras, [p], DisplaySettings(), "ghost")


def test_empty_panels_raises() -> None:
    """At least one panel is mandatory."""
    with pytest.raises(ValueError):
        generate_viewpie_yaml({}, [], DisplaySettings(), "x")


def test_generate_panel_yaml_fragment() -> None:
    """Single-panel fragment exposes id/name/layout and optional overrides."""
    p = Panel(
        id="frag",
        name="Fragment",
        layout="a b c\nd e f\ng h i",
        viewports=[Viewport(slot="s", feeds=["a"])],
        background="#ffffff",
    )
    doc = yaml.safe_load(generate_panel_yaml(p))
    assert doc["panel"]["id"] == "frag"
    assert doc["panel"]["background"] == "#ffffff"
    assert doc["panel"]["slots"] == ["s"]


def test_generate_panel_yaml_from_blocks() -> None:
    """Blocks-only panels rebuild layout text automatically."""
    p = Panel(id="b", name="B", layout="", viewports=[])
    blocks = [Block(label="x", camera_name="x", top=0, left=0, width=2, height=2)]
    doc = yaml.safe_load(generate_panel_yaml(p, blocks))
    assert doc["panel"]["layout"].startswith("x x .")


def test_blocks_to_layout_text() -> None:
    """Explicit rectangles render to canonical grid text with dots."""
    blocks = [
        Block(label="m", camera_name="m", top=0, left=0, width=2, height=1),
        Block(label="n", camera_name="n", top=2, left=2, width=1, height=1),
    ]
    text = blocks_to_layout_text(blocks, 3)
    assert text == "m m .\n. . .\n. . n"


def test_camera_to_feed_minimal() -> None:
    """Without fullscreen_url only the url key is emitted."""
    feed = camera_to_feed(Camera(name="c", url="rtsp://h/s"))
    assert feed == {"url": "rtsp://h/s"}
